INSERT INTO `sys_oper_log` VALUES (1911708445732511746, '000000', '档案分类模版和字段', 5, 'org.dromara.templatedata.controller.EcTemplateFieldController.exportTemplate()', 'POST', 1, 'admin', '研发部门', '/data/templateField/exportTemplate', '127.0.0.1', '内网IP', '', '', 1, '\r\n### Error querying database.  Cause: com.baomidou.mybatisplus.core.exceptions.MybatisPlusException: Failed to process, Error SQL: SELECT id, template_name, version_num, category_type, template_describe\n        FROM (\n                 SELECT id, template_name, version_num, category_type, template_describe\n                        ROW_NUMBER() OVER (PARTITION BY category_type\n                                      ORDER BY CAST(version_num AS FLOAT) DESC) AS rn\n                 FROM ec_template_type\n                 WHERE version_type = 1 AND del_flag = 0\n             ) tmp\n        WHERE rn = 1\r\n### Cause: com.baomidou.mybatisplus.core.exceptions.MybatisPlusException: Failed to process, Error SQL: SELECT id, template_name, version_num, category_type, template_describe\n        FROM (\n                 SELECT id, template_name, version_num, category_type, template_describe\n                        ROW_NUMBER() OVER (PARTITION BY category_type\n                                      ORDER BY CAST(version_num AS FLOAT) DESC) AS rn\n                 FROM ec_template_type\n                 WHERE version_type = 1 AND del_flag = 0\n             ) tmp\n        WHERE rn = 1', '2025-04-14 17:09:46', 27);
