-- ----------------------------
-- Table structure for four_property_check
-- ----------------------------
DROP TABLE IF EXISTS `four_property_check`;
CREATE TABLE `four_property_check`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键自增ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测项目',
  `group_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测项目分组',
  `type` int NOT NULL COMMENT '检测类型 1:真实性, 2:完整性, 3:可用性, 4:安全性',
  `segment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测环节 归档环节, 移交与接收环节, 长期保存环节',
  `objective` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测目的',
  `default_through` int NOT NULL COMMENT '是否默认通过 1：开启，0：关闭',
  `enabled` int NOT NULL COMMENT '是否开启 1：开启，0：关闭',
  `create_dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `tenant_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租户id',
  `segment_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测环节分组编码',
  `number` int NOT NULL COMMENT '规则编号用于程序必填',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1945032273979846664 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '四性检测表' ROW_FORMAT = Dynamic;

