  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1932736835012526082 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '四性检测明细表' ROW_FORMAT = Dynamic;

