-- ----------------------------
-- Table structure for sys_upload_detail
-- ----------------------------
DROP TABLE IF EXISTS `sys_upload_detail`;
CREATE TABLE `sys_upload_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分片主键',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名称',
  `md5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'MD5值',
  `is_uploaded` tinyint NULL DEFAULT 0 COMMENT '是否完整上传过 0：否 1：是',
  `has_been_uploaded` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '曾经上传过的分片号',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存储的url',
  `tenant_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '删除标识(0-正常 1-已删除)',
  `total_chunks` int NULL DEFAULT NULL COMMENT '文件的总分片数',
  `object_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存储对象键',
  `oss_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1983738582862041091 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件分片对象' ROW_FORMAT = Dynamic;

