-- ----------------------------
-- Table structure for tree_node
-- ----------------------------
DROP TABLE IF EXISTS `tree_node`;
CREATE TABLE `tree_node`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键自增ID',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '父节点ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点名称',
  `weight` int NOT NULL COMMENT '层级 1:年, 2:月, 3:公司, 4:分类',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点路径（用于层级查询）',
  `bound_field` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绑定字段：year/month/companyId/archiveType',
  `create_dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `tenant_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '租户id',
  `tree_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '树形结构类型(invoice-发票树型结构,voucher-凭证树形结构)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2008100954720706563 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '树形结构维护表\r\n' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tree_node
-- ----------------------------

-- ----------------------------
-- Table structure for warehouse_management_counter
-- ----------------------------
DROP TABLE IF EXISTS `warehouse_management_counter`;
CREATE TABLE `warehouse_management_counter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `resource_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源类型：WAREHOUSE-库房/ARCHIVE_CABINET-密集柜/ARCHIVE_LAYER-档案柜/ARCHIVE_BOX-档案盒',
  `resource_id` bigint NULL DEFAULT NULL COMMENT '关联的资源ID,资源类型上级Id',
  `serial_number_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流水号（生成盒号的时候才会用到）',
  `current_count` int NULL DEFAULT 1 COMMENT '当前计数值',
  `prefix` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '编号前缀',
  `suffix` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '号' COMMENT '编号后缀',
  `description` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计数器描述',
  `version` int NULL DEFAULT 0 COMMENT '版本',
  `create_by` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_dept` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建部门',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '删除标志（0代表存在 2代表删除）',
  `tenant_id` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_resource`(`resource_type` ASC, `resource_id` ASC) USING BTREE COMMENT '资源类型和ID唯一索引',
  INDEX `idx_resource_id`(`resource_id` ASC) USING BTREE COMMENT '资源ID索引'
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库房管理计数器表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of warehouse_management_counter
-- ----------------------------

-- ----------------------------
-- Table structure for workbench_config
-- ----------------------------
DROP TABLE IF EXISTS `workbench_config`;
CREATE TABLE `workbench_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置主键ID',
  `workbench_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作台类型(receipt-回单 invoice-发票)',
  `execute_frequency` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行频率 采集凭证后=1/采集回单后=2/每天0点=3',
  `execute_scope` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行范围',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `is_auto_match` tinyint NULL DEFAULT NULL COMMENT '0-否 1-是 (是否自动匹配)',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '删除标识(0-正常 1-已删除)',
  `tenant_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1950132927992541187 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工作台配置主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workbench_config
-- ----------------------------

-- ----------------------------
-- Table structure for workbench_log
-- ----------------------------
DROP TABLE IF EXISTS `workbench_log`;
CREATE TABLE `workbench_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '操作记录ID',
  `rule_id` bigint UNSIGNED NOT NULL COMMENT '关联 workbench_match_rule.id',
  `config_id` bigint UNSIGNED NOT NULL COMMENT '关联 workbench_config.id',
  `operation_type` tinyint NOT NULL COMMENT '操作类型：1-新增 2-删除',
  `tenant_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '租户ID（适配多租户场景）',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
